-- Mistério em Montes Claros - banco do caso
-- Gerado por gerar_banco.py  |  MySQL 8 / phpMyAdmin

SET NAMES utf8mb4;

DROP DATABASE IF EXISTS misterio_sql;
CREATE DATABASE misterio_sql CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE misterio_sql;

CREATE TABLE cnh (
    id             INT PRIMARY KEY,
    idade          INT,
    altura         INT,
    cor_olhos      VARCHAR(20),
    cor_cabelo     VARCHAR(20),
    genero         VARCHAR(20),
    placa_veiculo  CHAR(7),
    marca_veiculo  VARCHAR(30),
    modelo_veiculo VARCHAR(30)
) ENGINE=InnoDB;

CREATE TABLE pessoa (
    id              INT PRIMARY KEY,
    nome            VARCHAR(80),
    id_cnh          INT NULL,
    endereco_numero INT,
    endereco_rua    VARCHAR(60),
    cpf             CHAR(11),
    UNIQUE KEY uk_pessoa_cpf (cpf),
    CONSTRAINT fk_pessoa_cnh FOREIGN KEY (id_cnh) REFERENCES cnh (id)
) ENGINE=InnoDB;

CREATE TABLE boletim_ocorrencia (
    id        INT AUTO_INCREMENT PRIMARY KEY,
    data      DATE,
    tipo      VARCHAR(40),
    descricao VARCHAR(500),
    cidade    VARCHAR(40)
) ENGINE=InnoDB;

CREATE TABLE entrevista (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    id_pessoa   INT,
    transcricao VARCHAR(600),
    CONSTRAINT fk_entrevista_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa (id)
) ENGINE=InnoDB;

CREATE TABLE academia_membro (
    id          VARCHAR(10) PRIMARY KEY,
    id_pessoa   INT,
    nome        VARCHAR(80),
    data_inicio DATE,
    situacao    VARCHAR(10),
    CONSTRAINT fk_membro_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa (id)
) ENGINE=InnoDB;

CREATE TABLE academia_checkin (
    id           INT AUTO_INCREMENT PRIMARY KEY,
    id_membro    VARCHAR(10),
    data         DATE,
    hora_entrada TIME,
    hora_saida   TIME,
    CONSTRAINT fk_checkin_membro FOREIGN KEY (id_membro) REFERENCES academia_membro (id)
) ENGINE=InnoDB;

CREATE TABLE checkin_evento (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    id_pessoa   INT,
    id_evento   INT,
    nome_evento VARCHAR(60),
    data        DATE,
    CONSTRAINT fk_evento_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa (id)
) ENGINE=InnoDB;

CREATE TABLE renda (
    cpf         CHAR(11) PRIMARY KEY,
    renda_anual INT,
    CONSTRAINT fk_renda_pessoa FOREIGN KEY (cpf) REFERENCES pessoa (cpf)
) ENGINE=InnoDB;

